cy.get('svg.chakra-icon.css-6ey7w3').eq(0).scrollIntoView().click();
cy.wait(500);
cy.get('body').should('contain', 'Bulk Qr Generate');
cy.contains('Bulk Qr Generate').click();
cy.contains('NotDownloaded QR Count:').invoke('text').then(text => {
  const match = text.match(/\d+/);
  const count = match ? parseInt(match[0], 10) : 0;
  cy.log('Extracted Count:', count);
  if (count > 0) {
    cy.get('input.chakra-input.css-1cjy4zv').eq(1).type('1');
    cy.contains('Download Excel').click();
    cy.wait(5000);
    cy.task("countFilesInDownloads").then(count => {
      cy.log("Total files in downloads folder:", count);
    });
    cy.task("getLatestFile").then(latestFile => {
      cy.log("Latest file found:", latestFile);
      if (latestFile) {
        const fileNameWithoutExtension = latestFile.replace(/\.xlsx$/, ""); // Remove `.xlsx`
        cy.wait(1500);
        cy.verifyDownload(fileNameWithoutExtension);
      }
    });
  }
});
